// Cloudflare Workers entry point. Wraps the OpenNext-generated worker so the
// per-request MongoDB client opened by lib/db.ts is closed once the response
// has been fully sent (see the Workers notes in lib/db.ts).
import { DurableObject } from "cloudflare:workers";
// @ts-ignore `.open-next/worker.js` is generated by `opennextjs-cloudflare build`
import { default as handler } from "./.open-next/worker.js";
import type { RealtimeMessage } from "./realtime-hub";
export { RealtimeHub } from "./realtime-hub";

const REQUEST_DBS = Symbol.for("valueplus.requestDbs");

function closeRequestDb(ctx: ExecutionContext) {
  const requestDbs: WeakMap<object, { client: { close(): Promise<void> } }> | undefined =
    (globalThis as any)[REQUEST_DBS];
  const entry = requestDbs?.get(ctx);
  if (!entry) return Promise.resolve();
  requestDbs!.delete(ctx);
  return entry.client.close().catch(() => {});
}

// Local-only maintenance/debug routes. None of them check who is calling
// (/api/seed wipes and re-seeds the whole database, import-stock deletes every
// item), several read files from the developer's disk, and the UI never calls
// them — so the public deployment does not serve them at all.
const BLOCKED_API_PREFIXES = [
  "/api/seed",
  // Resets the demo accounts (admin@valueplus.in …) to default passwords;
  // NextAuth's middleware skips /api/auth/*, so nothing else guards it.
  "/api/auth/seed",
  "/api/install-deps",
  "/api/test-login",
  "/api/fix-invoices",
  "/api/db-check",
  "/api/admin/import-stock",
  "/api/admin/import-stock4",
  "/api/admin/debug-stock",
];

function isBlocked(pathname: string) {
  const path = pathname.toLowerCase().replace(/\/+$/, "");
  return BLOCKED_API_PREFIXES.some((p) => path === p || path.startsWith(`${p}/`));
}

// ---------------------------------------------------------------------------
// Live updates (see realtime-hub.ts). The app opens one WebSocket at /realtime;
// after every successful write to /api/* the path is announced on it, and the
// screens showing that data fetch it again. This replaces the timers that used
// to ask the server every few seconds whether anything had changed.
// ---------------------------------------------------------------------------
const REALTIME_PATH = "/realtime";

function realtimeHub(env: any) {
  const ns = env?.REALTIME;
  return ns ? ns.get(ns.idFromName("global")) : null;
}

/** The API path a write changed, as the screens subscribe to it; null for writes nobody watches. */
function changedPath(pathname: string): string | null {
  const path = pathname.toLowerCase().replace(/\/+$/, "");
  if (!path.startsWith("/api/")) return null;
  if (["/api/auth/", "/api/push/", "/api/cron/"].some((p) => path.startsWith(p))) return null;
  // Marking a notification read concerns only its reader's bell (sent to them by lib/notify.ts when one is
  // created); what others see from it is the task's "Read by", announced under its own name.
  if (path === "/api/notifications") return "notification-read";
  return path;
}

function publish(env: any, ctx: ExecutionContext, msg: RealtimeMessage) {
  const hub = realtimeHub(env);
  if (!hub) return;
  ctx.waitUntil(
    hub
      .fetch("https://realtime/publish", { method: "POST", body: JSON.stringify(msg) })
      .catch((e: unknown) => console.warn("realtime publish failed:", e))
  );
}

/** Signed-in user of a request, read the way the app reads it (NextAuth's own session endpoint). */
async function sessionUser(request: Request, env: unknown, ctx: ExecutionContext): Promise<{ id: string; role: string } | null> {
  const origin = new URL(request.url).origin;
  const res: Response = await handler.fetch(
    new Request(`${origin}/api/auth/session`, { headers: { cookie: request.headers.get("cookie") || "" } }),
    env,
    ctx
  );
  if (!res.ok) return null;
  const json: any = await res.json().catch(() => null);
  const user = json?.user;
  return user?.id ? { id: String(user.id), role: String(user.role || "") } : null;
}

async function connectRealtime(request: Request, env: any, ctx: ExecutionContext): Promise<Response> {
  if (request.headers.get("Upgrade")?.toLowerCase() !== "websocket") {
    return new Response("Expected a WebSocket", { status: 426 });
  }
  // Only the app's own pages may open it (a browser always sends Origin on a WebSocket).
  const origin = request.headers.get("Origin");
  if (origin && new URL(origin).host !== new URL(request.url).host) {
    return new Response("Forbidden", { status: 403 });
  }
  const hub = realtimeHub(env);
  if (!hub) return new Response("Not found", { status: 404 });
  const user = await sessionUser(request, env, ctx);
  if (!user) return new Response("Sign in first", { status: 401 });

  const headers = new Headers(request.headers);
  headers.set("x-user-id", user.id);
  headers.set("x-user-role", user.role);
  return hub.fetch(new Request("https://realtime/connect", { headers }));
}

export default {
  // Cron (wrangler.jsonc "triggers"), every 5 minutes:
  //  - 10:00-10:04 India time (the 10:00 run) -> "office time has started" for all staff (once a day);
  //  - always -> attendance alerts (not checked in from 10:00, break over and not at the store).
  async scheduled(_event: unknown, env: any, ctx: ExecutionContext) {
    const hit = async (path: string) => {
      try {
        const req = new Request(`https://scheduled.internal${path}`, { headers: { "x-cron-key": String(env?.NEXTAUTH_SECRET || "") } });
        const res = env?.WORKER_SELF_REFERENCE ? await env.WORKER_SELF_REFERENCE.fetch(req) : await (this as any).fetch(req, env, ctx);
        console.log(`${path} cron:`, res.status);
      } catch (e) {
        console.warn(`${path} cron failed:`, e);
      }
    };
    const ist = new Date(Date.now() + 5.5 * 3600 * 1000);
    if (ist.getUTCHours() === 10 && ist.getUTCMinutes() < 5) ctx.waitUntil(hit("/api/cron/office-start"));
    ctx.waitUntil(hit("/api/cron/attendance"));
  },

  async fetch(request: Request, env: unknown, ctx: ExecutionContext): Promise<Response> {
    const pathname = new URL(request.url).pathname;
    if (isBlocked(pathname)) {
      return new Response("Not found", { status: 404 });
    }
    if (pathname === REALTIME_PATH) {
      return connectRealtime(request, env, ctx);
    }

    let response: Response;
    try {
      response = await handler.fetch(request, env, ctx);
    } catch (e) {
      ctx.waitUntil(closeRequestDb(ctx));
      throw e;
    }

    // A write went through: tell the open apps what changed.
    if (request.method !== "GET" && request.method !== "HEAD" && response.status < 400) {
      const changed = changedPath(pathname);
      if (changed) publish(env, ctx, { paths: [changed] });
    }

    const requestDbs = (globalThis as any)[REQUEST_DBS] as WeakMap<object, unknown> | undefined;
    if (!requestDbs?.has(ctx)) {
      return response;
    }

    // A streamed body may still be reading from the database, so wait for it
    // to finish before closing the client.
    if (!response.body || (response as any).webSocket) {
      ctx.waitUntil(closeRequestDb(ctx));
      return response;
    }
    const { readable, writable } = new TransformStream();
    ctx.waitUntil(
      response.body
        .pipeTo(writable)
        .catch(() => {})
        .finally(() => closeRequestDb(ctx))
    );
    return new Response(readable, response);
  },
};

// @ts-ignore
export * from "./.open-next/worker.js";

// An earlier deployment of the production Worker ran the app inside this
// Durable Object, and Cloudflare refuses a new version that drops a class an
// existing namespace depends on. It is no longer used for any request; it is
// kept (instead of a delete-class migration) so a rollback to that older
// version stays possible.
export class AppServer extends DurableObject {
  async fetch(): Promise<Response> {
    return new Response("Not found", { status: 404 });
  }
}
